def refs():
    return [{**s, "subject": "math", "locator": "空間中直線與平面的位置關係、平行、垂直、相交平面與立體圖形", "observedPattern": "公開數學評量常以立體圖形或幾何敘述判斷線面平行、線面垂直、兩平面交線與空間距離；本題只取能力方向、敘述型態與判理層次。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, answer, explanation, strategy, steps, difficulty):
    return {"id": f"question-math-performance-s-iv-15-{n}", "subject": "math", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三份公立學校／公開會考數學試題僅供空間線面位置關係、立體幾何與判理能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公開數學試題的空間幾何方向獨立改寫；題幹、數值、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "直線 l 垂直於平面 α 內相交於同一點的兩條直線 m、n，則 l 與平面 α 的關係為何？", {"A": "l 平行於 α", "B": "l 垂直於 α", "C": "l 在 α 內", "D": "無法判定"}, "B", "一條直線若垂直於平面內同一點相交的兩條直線，依線面垂直判定，該直線垂直於平面 α，選 B。", "先檢查兩條已知直線是否在同一平面且相交於同一點；這是線面垂直判定的關鍵，不可只看一條。", ["確認 m、n 都位於平面 α。", "確認 m、n 在同一點相交。", "判斷 l 同時垂直 m 與 n。", "套用線面垂直判定定理。", "得到 l⊥α，選 B。"], "medium"),
    make(2, "在同一平面內，兩條沒有任何交點的直線稱為什麼？", {"A": "相交線", "B": "平行線", "C": "垂直線", "D": "異面直線"}, "B", "同一平面內的兩直線若不相交，就稱為平行線，選 B；異面直線不在同一平面內。", "先辨認『同一平面』這個限制，再排除只適用於空間的異面直線。", ["讀取條件：兩線在同一平面。", "排除相交線，因題目說沒有交點。", "排除垂直線，垂直線必須相交。", "同平面不相交的兩線定義為平行線。", "所以選 B。"], "easy"),
    make(3, "一個正方體共有幾個面？", {"A": "6 個", "B": "8 個", "C": "10 個", "D": "12 個"}, "A", "正方體由上、下、前、後、左、右六個全等正方形面組成，選 A。", "從立體的三組相對面計數：每一組方向有兩面，共三組。", ["先找上下兩個相對面。", "再找前後兩個相對面。", "最後找左右兩個相對面。", "合計 2＋2＋2＝6 個面。", "因此選 A。"], "easy"),
    make(4, "直線 l 與平面 α 內的一條直線 m 平行，僅由此條件能否判定 l 與 α 平行？", {"A": "一定可以，因為 l∥m", "B": "一定不可以，因為 l 必在 α 內", "C": "不能直接判定，還需要其他條件", "D": "一定垂直於 α"}, "C", "l 與平面內一條直線平行，可能與平面平行，也可能就在平面內，單一平行條件不足以判定線面關係，選 C。", "把『一條平面內直線』與『整個平面』分開比較；線線平行不等於線面平行。", ["記下已知只有 l∥m。", "m 位於平面 α，但 l 的位置尚未確定。", "l 可能在 α 內，也可能在 α 外且與 α 平行。", "因此必須補充 l 不在 α 內等條件。", "結論是不能直接判定，選 C。"], "medium"),
    make(5, "兩個不重合的平面 α、β 若相交，其交集通常是什麼？", {"A": "一個點", "B": "一條直線", "C": "一個圓", "D": "整個空間"}, "B", "兩個不重合平面相交時，共同部分沿著一條直線延伸，稱為兩平面的交線，選 B。", "想像兩張平面紙片相切並延展；共同的整條邊界不是單一點。", ["確認兩平面不重合且確實相交。", "找出同時屬於 α、β 的共同點。", "若有兩個不同共同點，兩點決定一條直線。", "兩平面的共同部分沿此直線延伸。", "所以交集是直線，選 B。"], "easy"),
    make(6, "若直線 l 垂直於平面 α 內相交於 P 的兩條直線 m、n，哪一個敘述必然正確？", {"A": "l 與 α 平行", "B": "l 垂直於 α", "C": "l 在 α 內且通過 P", "D": "l 與 α 沒有公共點"}, "B", "同一點相交的兩條平面內直線可作為線面垂直的判定條件，所以 l⊥α，選 B。", "抓住『兩條相交』與『同一點』，再套用線面垂直判定，而不是把垂直誤看成平行。", ["確認 m、n 都在 α 內。", "確認它們在 P 相交。", "已知 l 同時垂直 m、n。", "由判定定理推出 l 垂直整個 α。", "所以選 B。"], "medium"),
    make(7, "兩平面 α、β 相交於直線 k；若直線 l 在 α 內、l 不等於 k 且 l∥k，則 l 與 β 的關係為何？", {"A": "l∥β", "B": "l⊥β", "C": "l 與 β 相交於一點", "D": "l 必在 β 內"}, "A", "l 位於 α 且與 α、β 的交線 k 平行，因此 l 不會碰到 β；它與 β 平行，選 A。", "先利用 l∥k 排除與 β 的交點，再用 l 不等於 k 排除 l 是交線本身。", ["知道 α∩β＝k。", "l 在 α 內但不等於 k。", "l∥k，所以 l 在 α 內不會與 k 相交。", "若 l 與 β 有共同點，該點也會在 k 上，會造成矛盾。", "因此 l∥β，選 A。"], "hard"),
    make(8, "若平面 α 與平面 β 平行，且直線 l 垂直於 α，則 l 與 β 的關係為何？", {"A": "l 平行於 β", "B": "l 垂直於 β", "C": "l 在 β 內", "D": "l 與 β 重合"}, "B", "兩平面平行時，共同的法線方向相同；垂直於 α 的直線也垂直於 β，選 B。", "把平行平面想成固定間距的兩層，穿越其中一層的法線方向也垂直另一層。", ["確認 α∥β，兩平面方向一致。", "l⊥α 表示 l 是 α 的法線方向。", "平行平面共享相同的法線方向。", "所以 l 也垂直 β。", "選 B。"], "medium"),
    make(9, "兩個互相平行的平面 α、β 之間，任取一條同時垂直兩平面的線段，其長度有何特徵？", {"A": "都相等，代表兩平面的距離", "B": "一定等於零", "C": "會隨位置改變且無法比較", "D": "一定等於其中一平面的面積"}, "A", "平行平面間的垂直距離處處相等；任取垂直兩平面的最短線段，其長度就是兩平面的距離，選 A。", "分辨垂直距離與斜線長度；平行平面之間的法向間隔固定。", ["確認兩平面互相平行。", "取同一法線方向連接兩平面。", "垂直線段代表兩平面的最短間隔。", "平行平面間隔固定，所以各段長相等。", "選 A。"], "medium"),
    make(10, "一條空間直線 l 只與平面 α 內的一條直線 m 平行，關於 l 與 α 的位置，下列何者正確？", {"A": "必定在 α 內", "B": "必定垂直 α", "C": "資料不足，可能在 α 內或與 α 平行", "D": "必定與 α 相交於一點"}, "C", "線 l 與平面內的 m 平行並不足夠；l 可能就是 α 內的另一條平行線，也可能在 α 外與 α 平行，選 C。", "用兩個合法模型反例檢查結論：同平面平行與平面外平行都符合已知條件。", ["先保留已知 l∥m 且 m⊂α。", "模型一：令 l 也在 α 內，條件成立。", "模型二：令 l 在 α 外且與 α 平行，條件仍成立。", "兩個模型結果不同，表示條件無法唯一決定。", "所以選 C。"], "medium"),
]

